c.cpp:
class Solution {
public:
    string encode(int num) {
        long long n = (long long)num + 1;
        int len = 0;
        while ((1LL << (len + 1)) <= n) len++;
        long long r = n - (1LL << len);
        string res;
        if (len == 0) return "";
        for (int i = len - 1; i >= 0; i--) res += ((r >> i) & 1) ? '1' : '0';
        return res;
    }
};

c.java:
class Solution {
    public String encode(int num) {
        long n = (long) num + 1;
        int len = 64 - Long.numberOfLeadingZeros(n) - 1;
        long r = n - (1L << len);
        StringBuilder sb = new StringBuilder();
        for (int i = len - 1; i >= 0; i--) sb.append((r >> i) & 1);
        return sb.toString();
    }
}

